import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.BBd5PKnH.js";const k=JSON.parse('{"title":"Bastion Host — Kết nối vào mạng nội bộ AWS","description":"","frontmatter":{"title":"Bastion Host — Kết nối vào mạng nội bộ AWS","date":"2026-05-29T00:00:00.000Z"},"headers":[],"relativePath":"notes/bastion-host-ket-noi-vao-mang-noi-bo-aws.md","filePath":"notes/bastion-host-ket-noi-vao-mang-noi-bo-aws.md"}'),h={name:"notes/bastion-host-ket-noi-vao-mang-noi-bo-aws.md"};function e(p,s,o,l,r,c){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h2 id="cau-chuyen-thuc-te" tabindex="-1">Câu chuyện thực tế <a class="header-anchor" href="#cau-chuyen-thuc-te" aria-label="Permalink to &quot;Câu chuyện thực tế&quot;">​</a></h2><p>Hôm đó mình cần kết nối vào RDS PostgreSQL đang chạy trong private subnet của VPC. RDS không có public endpoint. Nhưng tôi cần debug dữ liệu ngay lập tức.</p><p>Giải pháp: SSH vào một EC2 có public DNS, rồi <strong>forward port</strong> từ máy local xuống RDS thông qua con EC2 đó.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myphan.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5433:my-rds.cluster-xxx.ap-southeast-1.rds.amazonaws.com:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ec2-user@ec2-xx-xx-xx-xx.ap-southeast-1.compute.amazonaws.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -N</span></span></code></pre></div><p>Sau đó kết nối bình thường:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5433</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mydb</span></span></code></pre></div><p>Con EC2 đó chính là <strong>Bastion Host</strong>.</p><h2 id="bastion-host-la-gi" tabindex="-1">Bastion Host là gì? <a class="header-anchor" href="#bastion-host-la-gi" aria-label="Permalink to &quot;Bastion Host là gì?&quot;">​</a></h2><p>Bastion Host (hay Jump Server) là một server đặc biệt nằm ở vùng DMZ — có thể truy cập từ internet, nhưng đóng vai trò <strong>cửa ngõ duy nhất</strong> để vào hạ tầng nội bộ.</p><blockquote><p>⚠️ Ảnh thiếu: <strong>ChatGPT Image May 29, 2026, 03_31_40 PM.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><h2 id="cach-ssh-port-forwarding-hoat-đong" tabindex="-1">Cách SSH Port Forwarding hoạt động <a class="header-anchor" href="#cach-ssh-port-forwarding-hoat-đong" aria-label="Permalink to &quot;Cách SSH Port Forwarding hoạt động&quot;">​</a></h2><p>Khi chạy lệnh:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5433:rds-host:5432</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@bastion</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span></span></code></pre></div><p>Máy tính của bạn sẽ lắng nghe port <code>5432</code>. Mọi kết nối tới <code>localhost:5432</code> được SSH tunnel chuyển tiếp tới <code>rds-host:5432</code> — <strong>thông qua</strong> bastion, từ góc nhìn của mạng nội bộ AWS.</p><h2 id="security-group-can-cau-hinh-nhu-the-nao" tabindex="-1">Security Group cần cấu hình như thế nào? <a class="header-anchor" href="#security-group-can-cau-hinh-nhu-the-nao" aria-label="Permalink to &quot;Security Group cần cấu hình như thế nào?&quot;">​</a></h2><p><strong>Bastion EC2 — Inbound:</strong></p><blockquote><p>⚠️ Ảnh thiếu: <strong>Screenshot 2026-05-29 at 15.36.50.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p><strong>RDS — Inbound:</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Port</th><th>Source</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>5432</td><td>Security Group của Bastion</td></tr></tbody></table><p>Không bao giờ mở RDS ra <code>0.0.0.0/0</code></p><hr><h2 id="cau-lenh-hay-dung" tabindex="-1">Câu lệnh hay dùng <a class="header-anchor" href="#cau-lenh-hay-dung" aria-label="Permalink to &quot;Câu lệnh hay dùng&quot;">​</a></h2><p><strong>Kết nối có tunnel (chạy nền):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5433:rds-endpoint:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ec2-user@bastion-ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -fN</span></span></code></pre></div><p><strong>Kết nối vào app server qua bastion (ProxyJump):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -J</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ec2-user@bastion-ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ec2-user@private-app-ip</span></span></code></pre></div><p><strong>Cấu hình <code>~/.ssh/config</code> cho tiện:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host bastion</span></span>
<span class="line"><span>    HostName ec2-xx-xx.compute.amazonaws.com</span></span>
<span class="line"><span>    User ec2-user</span></span>
<span class="line"><span>    IdentityFile ~/.ssh/myphan.pem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Host rds-tunnel</span></span>
<span class="line"><span>    HostName localhost</span></span>
<span class="line"><span>    Port 5433</span></span>
<span class="line"><span>    LocalForward 5433 my-rds.xxx.rds.amazonaws.com:5432</span></span>
<span class="line"><span>    ProxyJump bastion</span></span></code></pre></div><p>Sau đó chỉ cần <code>ssh rds-tunnel -N</code> là xong.</p><p>Bastion Host là pattern đơn giản nhưng hiệu quả. Hiểu rõ nó giúp bạn vừa debug nhanh khi cần, vừa duy trì kiến trúc bảo mật đúng đắn.</p>`,30)])])}const g=a(h,[["render",e]]);export{k as __pageData,g as default};
